using Microsoft.Dynamics.Platform.Integration.Office;

/// <summary>
/// The <c>METLedgerDailyJournalExcelTemplate</c> is the supporting class for the Daily journal excel template.
/// Added for 174352 cross pillar journal import by anupama
/// </summary>
public class METLedgerDailyJournalExcelTemplate extends DocuTemplateRegistrationBase implements LedgerIJournalExcelTemplate
{
    private const DocuTemplateName ExcelTemplateName = resourceStr(METLedgerJournalGlobalLine);
    private const DataEntityName LineEntityName = tableStr(METLedgerJournalGlobalEntity);
    private const FieldName LineEntityJournalNum = fieldStr(METLedgerJournalGlobalEntity, JournalBatchNumber);
    private const FieldName LineEntityDataAreaId = fieldStr(METLedgerJournalGlobalEntity, dataAreaId);
    private const DataEntityName HeaderEntityName = tableStr(METLedgerJournalGlobalEntity);
    private const FieldName HeaderEntityJournalNum = fieldStr(METLedgerJournalGlobalEntity, JournalBatchNumber);
    private const FieldName HeaderEntityDataAreaId = fieldStr(METLedgerJournalGlobalEntity, dataAreaId);
    private const GlobalObjectCacheScope LedgerDailyJournalCacheScopeRecId = 'METLedgerDailyJournalCacheScopeRecId';
    private const GlobalObjectCacheScope LedgerDailyJournalCacheScopeResult = 'METLedgerDailyJournalCacheScopeResult';
    private const int64 JournalValidationFailed = -1;
    private const int64 JournalNotValidated = 0;

}

Method.Source:
/// <summary>
/// Retrieves the cached value for a given journal record ID.
/// </summary>
/// <param name="_scope">The cache scope.</param>
/// <param name="_journalRecId">The journal record ID.</param>
/// <returns>True if the value is cached; otherwise false.</returns>
private static boolean getCacheValue(GlobalObjectCacheScope _scope, RecId _journalRecId)
{
    SysGlobalCache c;

    c = classfactory.globalCache();

    return c.get(_scope, _journalRecId);
}

/// <summary>
/// Inserts a value into the cache for a given journal record ID.
/// </summary>
/// <param name="_scope">The cache scope.</param>
/// <param name="_journalRecId">The journal record ID.</param>
/// <param name="_value">The value to cache.</param>
private static void insertCacheValue(GlobalObjectCacheScope _scope, RecId _journalRecId, boolean _value)
{
    SysGlobalCache c;

    c = classfactory.globalCache();

    c.set(_scope, _journalRecId, _value);
}

/// <summary>
/// Retrieves the cached validation result for a given journal record ID.
/// </summary>
/// <param name="_scope">The cache scope.</param>
/// <param name="_journalRecId">The journal record ID.</param>
/// <returns>The cached validation result.</returns>
private static UnknownNoYes getCachedValidation(GlobalObjectCacheScope _scope, RecId _journalRecId)
{
    SysGlobalCache c;

    c = classfactory.globalCache();

    return c.get(_scope, _journalRecId);
}

/// <summary>
/// Sets the cached validation result for a given journal record ID.
/// </summary>
/// <param name="_scope">The cache scope.</param>
/// <param name="_journalRecId">The journal record ID.</param>
/// <param name="_value">The validation result to cache.</param>
private static void setCachedValidation(GlobalObjectCacheScope _scope, RecId _journalRecId, boolean _value)
{
    UnknownNoYes valueToStore;

    if (_value)
    {
        valueToStore = UnknownNoYes::Yes;
    }
    else
    {
        valueToStore = UnknownNoYes::No;
    }

    SysGlobalCache c;

    c = classfactory.globalCache();

    c.set(_scope, _journalRecId, valueToStore);
}

/// <summary>
/// Checks if the journal type is supported.
/// </summary>
/// <param name="_ledgerJournalType">The ledger journal type.</param>
/// <returns>True if the journal type is supported; otherwise false.</returns>
public boolean isJournalTypeSupported(LedgerJournalType _ledgerJournalType)
{
    return _ledgerJournalType == LedgerJournalType::Daily;
}

/// <summary>
/// Gets the document template name.
/// </summary>
/// <returns>The document template name.</returns>
public DocuTemplateName documentTemplateName()
{
    return ExcelTemplateName;
}

/// <summary>
/// Applies custom trimming to the template.
/// </summary>
/// <param name="_templateManager">The template manager.</param>
/// <param name="_settingsManager">The settings manager.</param>
/// <param name="_ledgerJournalTable">The ledger journal table.</param>
public void applyCustomTrimming(Excel.IWorkbookManager _templateManager, Excel.WorkbookSettingsManager _settingsManager, LedgerJournalTable _ledgerJournalTable)
{
}

/// <summary>
/// Gets the supported account types.
/// </summary>
/// <returns>A set of supported account types.</returns>
public Set supportedAccountTypes()
{
    Set accountTypeSet = new Set(Types::Integer);

    accountTypeSet.add(LedgerJournalACType::Ledger);
    accountTypeSet.add(LedgerJournalACType::Bank);
    accountTypeSet.add(LedgerJournalACType::Cust);
    accountTypeSet.add(LedgerJournalACType::Vend);

    return accountTypeSet;
}

/// <summary>
/// Gets the supported offset account types.
/// </summary>
/// <returns>A set of supported offset account types.</returns>
public Set supportedOffsetAccountTypes()
{
    Set offsetAccountTypeSet = new Set(Types::Integer);

    offsetAccountTypeSet.add(LedgerJournalACType::Ledger);
    offsetAccountTypeSet.add(LedgerJournalACType::Bank);
    offsetAccountTypeSet.add(LedgerJournalACType::Cust);
    offsetAccountTypeSet.add(LedgerJournalACType::Vend);

    return offsetAccountTypeSet;
}

/// <summary>
/// Validates the journal for the template.
/// </summary>
/// <param name="_ledgerJournalTable">The ledger journal table.</param>
/// <returns>True if the journal is valid for the template; otherwise false.</returns>
public boolean validateJournalForTemplate(LedgerJournalTable _ledgerJournalTable)
{
    return LedgerJournalExcelTemplate::validateJournalForTemplate(_ledgerJournalTable, this);
}

/// <summary>
/// Registers the templates.
/// </summary>
public void registerTemplates()
{
    this.addTemplate(
        OfficeAppApplicationType::Excel,
        ExcelTemplateName,
        ExcelTemplateName,
        literalStr("@MET:METGlobalJournalImport"),
        literalStr("@MET:METGlobalJournal"),
        NoYes::No,
        NoYes::No,
        NoYes::No);
}

/// <summary>
/// Gets the header entity name.
/// </summary>
/// <returns>The header entity name.</returns>
public DataEntityName headerEntityName()
{
    return HeaderEntityName;
}

/// <summary>
/// Gets the line entity name.
/// </summary>
/// <returns>The line entity name.</returns>
public DataEntityName lineEntityName()
{
    return LineEntityName;
}

/// <summary>
/// Gets the header journal batch-number field name.
/// </summary>
/// <returns>The header journal batch number field name.</returns>
public FieldName headerJournalBatchNumberFieldName()
{
    return HeaderEntityJournalNum;
}

/// <summary>
/// Gets the header data area field name.
/// </summary>
/// <returns>The header data area field name.</returns>
public FieldName headerDataAreaFieldName()
{
    return HeaderEntityDataAreaId;
}

/// <summary>
/// Gets the line journal batch number field name.
/// </summary>
/// <returns>The line journal batch number field name.</returns>
public FieldName lineJournalBatchNumberFieldName()
{
    return LineEntityJournalNum;
}

/// <summary>
/// Gets the line data area field name.
/// </summary>
/// <returns>The line data area field name.</returns>
public FieldName lineDataAreaFieldName()
{
    return LineEntityDataAreaId;
}

/// <summary>
/// Appends filters to the header entity.
/// </summary>
/// <param name="_headerFilter">The header filter collection node.</param>
/// <param name="_headerFilterBuilder">The header filter tree builder.</param>
/// <returns>The updated header filter collection node.</returns>
public FilterCollectionNode appendHeaderEntityFilters(FilterCollectionNode _headerFilter, ExportToExcelFilterTreeBuilder _headerFilterBuilder)
{
    return _headerFilter;
}

/// <summary>
/// Appends filters to the line entity.
/// </summary>
/// <param name="_lineFilter">The line filter collection node.</param>
/// <param name="_lineFilterBuilder">The line filter tree builder.</param>
/// <returns>The updated line filter collection node.</returns>
public FilterCollectionNode appendLineEntityFilters(FilterCollectionNode _lineFilter, ExportToExcelFilterTreeBuilder _lineFilterBuilder)
{
    return _lineFilter;
}

/// <summary>
/// Validates if the journal type is Daily.
/// </summary>
/// <param name="_journalTable">The ledger journal table.</param>
/// <param name="_cachedScope">The cache scope.</param>
/// <exception cref="Exception">Thrown when the journal type is not Daily.</exception>
private static void validateIsDailyJournalType(LedgerJournalTable _journalTable, GlobalObjectCacheScope _cachedScope)
{
    if (_journalTable.JournalType != LedgerJournalType::Daily)
    {
        METLedgerDailyJournalExcelTemplate::insertCacheValue(_cachedScope, _journalTable.RecId, METLedgerDailyJournalExcelTemplate::JournalValidationFailed);
        throw error(strFmt("@SYS114718", _journalTable.JournalName, LedgerJournalType::Daily));
    }
}

/// <summary>
/// Validates the header of the journal.
/// </summary>
/// <param name="_journalId">The journal ID.</param>
/// <returns>True if the header is valid; otherwise false.</returns>
private static boolean validateHeader(JournalId _journalId)
{
    LedgerJournalHeaderEntity header;
    select firstonly header where header.JournalBatchNumber == _journalId;

    return LedgerJournalEntityBase::validateJournal(header);
}

/// <summary>
/// Validates whether a journal is valid for use with the <c>LedgerDailyJournalExcelTemplate</c>. The state of the journal is
/// checked to verify inserts and updates are allowed.
/// </summary>
/// <param name = "_journalId">The name of the journal to validate.</param>
/// <returns>True if the journal type is valid for use with the template; otherwise false.</returns>
/// <remarks>Validation results are cached to improve import performance and eliminate redundant checks.</remarks>
public static boolean validateDailyJournal(JournalId _journalId)
{
    LedgerJournalTable journalTable = LedgerJournalTable::find(_journalId);
    boolean ret = false;

    UnknownNoYes cacheValue = METLedgerDailyJournalExcelTemplate::getCachedValidation(LedgerDailyJournalCacheScopeResult, journalTable.RecId);

    if (cacheValue == UnknownNoYes::Unknown)
    {
        METLedgerDailyJournalExcelTemplate::validateIsDailyJournalType(journalTable, LedgerDailyJournalCacheScopeResult);
        ret = METLedgerDailyJournalExcelTemplate::validateHeader(_journalId);

        METLedgerDailyJournalExcelTemplate::setCachedValidation(LedgerDailyJournalCacheScopeResult, journalTable.RecId, ret);
    }
    else
    {
        ret = (cacheValue == UnknownNoYes::Yes);
    }

    return ret;
}
